package codexhost

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/google/jsonschema-go/jsonschema"
)

// TestServerRequestDenialsMatchCodexSchema validates every denial payload
// against the schema generated by `codex app-server generate-json-schema`.
//
// The legacy approval methods take a ReviewDecision oneOf where "denied" is an
// object with a rejection string; a bare "denied" string would be rejected by
// Codex and hang the turn.
func TestServerRequestDenialsMatchCodexSchema(t *testing.T) {
	cases := []struct {
		method     string
		schemaFile string
	}{
		{methodCommandExecutionApproval, "CommandExecutionRequestApprovalResponse.json"},
		{methodFileChangeApproval, "FileChangeRequestApprovalResponse.json"},
		{methodApplyPatchApproval, "ApplyPatchApprovalResponse.json"},
		{methodExecCommandApproval, "ExecCommandApprovalResponse.json"},
		{methodToolRequestUserInput, "ToolRequestUserInputResponse.json"},
		{methodMCPServerElicitation, "McpServerElicitationRequestResponse.json"},
		{methodPermissionsApproval, "PermissionsRequestApprovalResponse.json"},
		{methodDynamicToolCall, "DynamicToolCallResponse.json"},
	}
	for _, testCase := range cases {
		t.Run(testCase.method, func(t *testing.T) {
			payload, rpcErr := answerServerRequest(testCase.method, json.RawMessage(`{"threadId":"t","turnId":"u"}`))
			if rpcErr != nil {
				t.Fatalf("unexpected JSON-RPC error: %+v", rpcErr)
			}
			validateAgainstCodexSchema(t, testCase.schemaFile, payload)
		})
	}
}

// TestCredentialRequestsReturnErrors checks that AgentDock never fabricates
// ChatGPT credentials or attestation tokens: both must surface as JSON-RPC
// errors rather than empty-but-valid responses.
func TestCredentialRequestsReturnErrors(t *testing.T) {
	for _, method := range []string{methodChatGPTAuthRefresh, methodAttestationGenerate} {
		payload, rpcErr := answerServerRequest(method, json.RawMessage(`{"reason":"expired"}`))
		if payload != nil {
			t.Fatalf("%s: expected no payload, got %v", method, payload)
		}
		if rpcErr == nil {
			t.Fatalf("%s: expected a JSON-RPC error", method)
		}
		if rpcErr.Code != codeCodexCredentialRequired {
			t.Fatalf("%s: unexpected error code %d", method, rpcErr.Code)
		}
	}
}

// TestUnknownServerRequestReturnsMethodNotFound guards against silently
// swallowing a request Codex expects a response to.
func TestUnknownServerRequestReturnsMethodNotFound(t *testing.T) {
	if _, rpcErr := answerServerRequest("some/future/method", nil); rpcErr == nil || rpcErr.Code != -32601 {
		t.Fatalf("expected -32601, got %+v", rpcErr)
	}
}

func validateAgainstCodexSchema(t *testing.T, schemaFile string, payload any) {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "schema", schemaFile))
	if err != nil {
		t.Fatalf("read schema %s: %v", schemaFile, err)
	}
	var schema jsonschema.Schema
	if err := json.Unmarshal(raw, &schema); err != nil {
		t.Fatalf("decode schema %s: %v", schemaFile, err)
	}
	resolved, err := schema.Resolve(nil)
	if err != nil {
		t.Fatalf("resolve schema %s: %v", schemaFile, err)
	}
	encoded, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("encode payload: %v", err)
	}
	var instance any
	if err := json.Unmarshal(encoded, &instance); err != nil {
		t.Fatalf("decode payload: %v", err)
	}
	if err := resolved.Validate(instance); err != nil {
		t.Fatalf("payload %s does not satisfy %s: %v", encoded, schemaFile, err)
	}
}
